114	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
115	     */
116	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
117	        List<String> missing = new ArrayList<>();
118	        if (isBlank(ownerFieldsDto.getFirstName())) {
119	            missing.add("firstName");
120	        }
121	        if (isBlank(ownerFieldsDto.getLastName())) {
122	            missing.add("lastName");
123	        }
124	        if (isBlank(ownerFieldsDto.getAddress())) {
125	            missing.add("address");
126	        }
127	        if (isBlank(ownerFieldsDto.getCity())) {
128	            missing.add("city");
129	        }
130	        if (isBlank(ownerFieldsDto.getTelephone())) {
131	            missing.add("telephone");
132	        }
133	        if (!missing.isEmpty()) {
134	            throw new RequiredFieldsMissingException(missing);
135	        }
136	    }
137	
138	    private static boolean isBlank(String value) {
139	        return value == null || value.isBlank();
140	    }
141	
142	    /**
143	     * Normalizes an address on create: leading/trailing whitespace is trimmed, every run of internal
144	     * whitespace is collapsed to a single space, the value is upper-cased and common abbreviations are
145	     * expanded token-by-token ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The
146	     * normalized value is what gets stored, returned and used for every address comparison; a value
147	     * that is blank (or {@code null}) normalizes to the empty string so the required-field check
148	     * rejects it.
149	     *
150	     * @param address the raw address as supplied by the caller, may be {@code null}
151	     * @return the normalized address ({@code ""} when blank or {@code null})
152	     */
153	    private static String normalizeAddress(String address) {
154	        if (address == null) {
155	            return "";
156	        }
157	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
158	        if (collapsed.isEmpty()) {
159	            return "";
160	        }
161	        String[] tokens = collapsed.split(" ");
162	        StringBuilder sb = new StringBuilder(collapsed.length());
163	        for (int i = 0; i < tokens.length; i++) {
164	            String token = tokens[i];
165	            switch (token) {
166	                case "ST" -> token = "STREET";
167	                case "RD" -> token = "ROAD";
168	                case "AVE" -> token = "AVENUE";
169	                default -> { }
170	            }
171	            if (i > 0) {
172	                sb.append(' ');
173	            }
174	            sb.append(token);
175	        }
176	        return sb.toString();
177	    }
178	
179	    /**
180	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
181	     * A leading {@code +} and its country code are kept as given; otherwise the country code
182	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
183	     * The result must carry 8 to 15 digits after the {@code +}. Returns the E.164 string to be
184	     * stored and returned.
185	     *
186	     * @param telephone the raw telephone as supplied by the caller
187	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
188	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
189	     */
190	    private static String normalizeTelephone(String telephone) {
191	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
192	        String e164;
193	        if (cleaned.startsWith("+")) {
194	            e164 = "+" + cleaned.substring(1);
195	        } else {
196	            String national = cleaned;
197	            if (national.startsWith("0")) {
198	                national = national.substring(1);
199	            }
200	            e164 = "+61" + national;
201	        }
202	        String digits = e164.substring(1);
203	        if (!digits.matches("\\d{8,15}")) {
204	            throw new InvalidTelephoneException(
205	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
206	        }
207	        return e164;
208	    }
209	
210	    /**
211	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
212	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
213	     *
214	     * @param email the raw email as supplied by the caller, may be {@code null}
215	     * @return the lower-cased email, or {@code null} when none was supplied
216	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
217	     */
218	    private static String normalizeEmail(String email) {
219	        if (email == null || email.isBlank()) {
220	            return null;
221	        }
222	        String trimmed = email.trim();
223	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
224	            throw new InvalidEmailException("Email must be a syntactically valid address");
225	        }
226	        return trimmed.toLowerCase(Locale.ROOT);
227	    }
228	
229	    /**
230	     * Rejects a create whose E.164 telephone is already used by any existing owner, so that
231	     * telephones stay unique across owners. Telephones are stored in E.164 form on create, so a
232	     * direct equality comparison of the E.164 values against the stored values is sufficient.
233	     *
234	     * @param normalizedTelephone the E.164 telephone of the owner being created
235	     * @throws DuplicateTelephoneException if another owner already uses this telephone
236	     */
237	    private void rejectDuplicateTelephone(String normalizedTelephone) {
238	        boolean inUse = this.clinicService.findAllOwners().stream()
239	            .anyMatch(existing -> normalizedTelephone.equals(existing.getTelephone()));
240	        if (inUse) {
241	            throw new DuplicateTelephoneException(
242	                "Telephone is already used by another owner");
243	        }
244	    }
245	
246	    /**
247	     * Rejects a create that would place the owner in a household already occupied by another owner,
248	     * i.e. one whose last name and address match the supplied values. The two fields are compared
249	     * case-insensitively after whitespace is collapsed (leading/trailing whitespace trimmed and each
250	     * run of internal whitespace reduced to a single space), so {@code '110 W.  Liberty St. '} and
251	     * {@code '110 w. liberty st.'} are treated as the same address. The caller may bypass this check
252	     * by setting {@code sharesHousehold} to {@code true}.
253	     *
254	     * @param lastName the last name of the owner being created
255	     * @param address the address of the owner being created
256	     * @throws DuplicateHouseholdException if another owner already shares this last name and address
257	     */
258	    private void rejectDuplicateHousehold(String lastName, String address) {
259	        String normalizedLastName = normalizeForHousehold(lastName);
260	        String normalizedAddress = normalizeForHousehold(address);
261	        boolean inHousehold = this.clinicService.findAllOwners().stream()
262	            .anyMatch(existing ->
263	                normalizedLastName.equals(normalizeForHousehold(existing.getLastName()))
264	                    && normalizedAddress.equals(normalizeForHousehold(existing.getAddress())));
265	        if (inHousehold) {
266	            throw new DuplicateHouseholdException(
267	                "An owner with the same last name and address already exists");
268	        }
269	    }
270	
271	    /**
272	     * Normalizes a value for household comparison by trimming, collapsing every run of whitespace to
273	     * a single space and lower-casing, so the comparison is case-insensitive with collapsed whitespace.
274	     *
275	     * @param value the raw value, may be {@code null}
276	     * @return the normalized value ({@code ""} when {@code value} is {@code null})
277	     */
278	    private static String normalizeForHousehold(String value) {
279	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
280	    }
281	
282	    /**
283	     * Derives the stable household identifier for an owner from the normalized last name and address.
284	     * The value is a deterministic function of those two fields (compared case-insensitively with
285	     * collapsed whitespace, exactly as {@link #rejectDuplicateHousehold}), so every owner in the same
286	     * household — including owners who knowingly join it via {@code sharesHousehold} — is assigned the
287	     * same identifier without any existing record having to be updated. Formatted {@code 'HH-<HEX12>'}
288	     * where {@code HEX12} is the upper-cased first twelve hex characters of the SHA-256 of the two
289	     * normalized fields.
290	     *
291	     * @param lastName the last name of the owner being created
292	     * @param address the address of the owner being created
293	     * @return the stable household identifier
294	     */
295	    private static String householdId(String lastName, String address) {
296	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
297	        try {
298	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
299	            StringBuilder sb = new StringBuilder(digest.length * 2);
300	            for (byte b : digest) {
301	                sb.append(String.format("%02x", b));
302	            }
303	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
304	        } catch (NoSuchAlgorithmException e) {
305	            throw new IllegalStateException("SHA-256 not available", e);
306	        }
307	    }
308	
309	    /**
310	     * The maximum number of owners a single city may contain. A create whose city already holds this
311	     * many owners is rejected, so a city never grows beyond this capacity.
312	     */
313	    private static final int CITY_CAPACITY = 50;
314	
315	    /**
316	     * Rejects a create whose city already contains {@link #CITY_CAPACITY} or more owners, so no city
317	     * ever exceeds its capacity. Cities are compared case-insensitively with surrounding whitespace
318	     * trimmed, exactly as {@link #nextCustomerCode} counts a city's owners. The count reflects the
319	     * state before the new owner is persisted, so it excludes the owner being created.
320	     *
321	     * @param city the city of the owner being created
322	     * @throws CityAtCapacityException if the city already contains {@link #CITY_CAPACITY} owners
323	     */
324	    private void rejectCityAtCapacity(String city) {
325	        String normalizedCity = normalizeName(city);
326	        long ownersInCity = this.clinicService.findAllOwners().stream()
327	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
328	            .count();
329	        if (ownersInCity >= CITY_CAPACITY) {
330	            throw new CityAtCapacityException(
331	                "The city already contains the maximum number of owners");
332	        }
333	    }
334	
335	    /**
336	     * The maximum number of owners that may be created on a single day. A create made once this many
337	     * owners already carry today's {@code registrationDate} is rejected, so no more than this many
338	     * owners are registered per day.
339	     */
340	    private static final int DAILY_OWNER_LIMIT = 100;
341	
342	    /**
343	     * Rejects a create once {@link #DAILY_OWNER_LIMIT} or more owners have already been created for
344	     * the given business day, counted by {@code registrationDate} equal to the effective (weekend
345	     * rolled forward) registration date of the owner being created. The count reflects the state
346	     * before the new owner is persisted, so it excludes the owner being created.
347	     *
348	     * @param registrationDate the effective business-day registration date of the owner being created
349	     * @throws DailyOwnerLimitExceededException if the day already holds {@link #DAILY_OWNER_LIMIT} owners
350	     */
351	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
352	        long ownersToday = this.clinicService.findAllOwners().stream()
353	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
354	            .count();
355	        if (ownersToday >= DAILY_OWNER_LIMIT) {
356	            throw new DailyOwnerLimitExceededException(
357	                "The maximum number of owners for today has already been reached");
358	        }
359	    }
360	
361	    /**
362	     * Rolls a registration date forward to a business day: a Saturday or Sunday is advanced to the
363	     * following Monday, any weekday is returned unchanged.
364	     *
365	     * @param date the effective registration date, supplied or defaulted to the server date
366	     * @return the same date when it is a weekday, otherwise the next Monday
367	     */
368	    private static LocalDate toBusinessDay(LocalDate date) {
369	        DayOfWeek dayOfWeek = date.getDayOfWeek();
370	        if (dayOfWeek == DayOfWeek.SATURDAY) {
371	            return date.plusDays(2);
372	        }
373	        if (dayOfWeek == DayOfWeek.SUNDAY) {
374	            return date.plusDays(1);
375	        }
376	        return date;
377	    }
378	
379	    /**
380	     * Builds the customer code assigned to an owner on create, formatted
381	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first three letters
382	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last
383	     * name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
384	     * current number of owners already in that city, e.g. {@code 'MEL-SMI-0007'}.
385	     *
386	     * @param city the city of the owner being created
387	     * @param lastName the last name of the owner being created
388	     * @return the formatted customer code
389	     */
390	    private String nextCustomerCode(String city, String lastName) {
391	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
392	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
393	        String normalizedCity = normalizeName(city);
394	        int sequence = (int) this.clinicService.findAllOwners().stream()
395	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
396	            .count() + 1;
397	        return String.format("%s-%s-%04d", city3, last3, sequence);
398	    }
399	
400	    /**
401	     * Counts the existing owners that share the owner-to-be's first and last name, compared
402	     * case-insensitively (surrounding whitespace trimmed). The count reflects the state before the
403	     * new owner is persisted, so it excludes the owner being created.
404	     *
405	     * @param firstName the first name of the owner being created
406	     * @param lastName the last name of the owner being created
407	     * @return the number of existing owners with the same first and last name
408	     */
409	    private int countNamesakes(String firstName, String lastName) {
410	        String normalizedFirstName = normalizeName(firstName);
411	        String normalizedLastName = normalizeName(lastName);
412	        return (int) this.clinicService.findAllOwners().stream()
413	            .filter(existing ->
414	                normalizedFirstName.equals(normalizeName(existing.getFirstName()))
415	                    && normalizedLastName.equals(normalizeName(existing.getLastName())))
416	            .count();
417	    }
418	
419	    /**
420	     * Normalizes a name for case-insensitive comparison by trimming surrounding whitespace and
421	     * lower-casing.
422	     *
423	     * @param value the raw name, may be {@code null}
424	     * @return the normalized name ({@code ""} when {@code value} is {@code null})
425	     */
426	    private static String normalizeName(String value) {
427	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
428	    }
429	
430	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
431	    @Override
432	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
433	        Owner owner = this.clinicService.findOwnerById(ownerId);
434	        if (owner == null) {
435	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
436	        }
437	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
438	    }
439	
440	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
441	    @Override
442	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
443	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
444	        validateRequiredFields(ownerFieldsDto);
445	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
446	        if (registrationDate == null) {
447	            registrationDate = LocalDate.now();
448	        }
449	        registrationDate = toBusinessDay(registrationDate);
450	        ownerFieldsDto.setRegistrationDate(registrationDate);
451	        rejectDailyOwnerLimit(registrationDate);
452	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
453	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
454	        }
455	        rejectCityAtCapacity(ownerFieldsDto.getCity());
456	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
457	        rejectDuplicateTelephone(normalizedTelephone);
458	        ownerFieldsDto.setTelephone(normalizedTelephone);
459	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
460	        HttpHeaders headers = new HttpHeaders();
461	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
462	        owner.setCustomerCode(nextCustomerCode(ownerFieldsDto.getCity(), ownerFieldsDto.getLastName()));
463	        owner.setHouseholdId(householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress()));
464	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
465	        this.clinicService.saveOwner(owner);
466	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
467	        headers.setLocation(UriComponentsBuilder.newInstance()
468	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
469	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
470	    }
471	
472	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
473	    @Override
474	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
475	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
476	        if (currentOwner == null) {
477	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
478	        }
479	        currentOwner.setAddress(ownerFieldsDto.getAddress());
480	        currentOwner.setCity(ownerFieldsDto.getCity());
481	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
482	        currentOwner.setLastName(ownerFieldsDto.getLastName());
483	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
484	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
485	        this.clinicService.saveOwner(currentOwner);
486	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
487	    }
488	
489	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
490	    @Transactional
491	    @Override
492	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
493	        Owner owner = this.clinicService.findOwnerById(ownerId);
494	        if (owner == null) {
495	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
496	        }
497	        this.clinicService.deleteOwner(owner);
498	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
499	    }
500	
501	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
502	    @Override
503	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
504	        Owner owner = this.clinicService.findOwnerById(ownerId);
505	        if (owner == null) {
506	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
507	        }
508	        HttpHeaders headers = new HttpHeaders();
509	        Pet pet = petMapper.toPet(petFieldsDto);
510	        owner.setId(ownerId);
511	        pet.setOwner(owner);
512	        pet.getType().setName(null);
513	        this.clinicService.savePet(pet);
514	        PetDto petDto = petMapper.toPetDto(pet);
515	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
516	            .buildAndExpand(pet.getId()).toUri());
517	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
518	    }
519	
520	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
521	    @Override
522	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
523	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
524	        if (currentOwner != null) {
525	            Pet currentPet = this.clinicService.findPetById(petId);
526	            if (currentPet != null) {
527	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
528	                currentPet.setName(petFieldsDto.getName());
529	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
530	                this.clinicService.savePet(currentPet);
531	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
532	            }
533	        }
534	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
535	    }
536	
537	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
538	    @Override
539	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
540	        HttpHeaders headers = new HttpHeaders();
541	        Visit visit = visitMapper.toVisit(visitFieldsDto);
542	        Pet pet = new Pet();
543	        pet.setId(petId);
544	        visit.setPet(pet);
545	        this.clinicService.saveVisit(visit);
546	        VisitDto visitDto = visitMapper.toVisitDto(visit);
547	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
548	            .buildAndExpand(visit.getId()).toUri());
549	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
550	    }
551	
552	
553	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
554	    @Override
555	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
556	        Owner owner = this.clinicService.findOwnerById(ownerId);
557	        if (owner != null) {
558	            Pet pet = owner.getPet(petId);
559	            if (pet != null) {
560	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
561	            }
562	        }
563	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
564	    }
565	}
